// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner")))));
        vm.prank(owner);
        c = new SimpleWallet();
        vm.deal(address(c), amount);
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        c.withdraw(amount);
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + amount);
    }
}
